#include <time.h>

static double now_seconds(void){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return(double)ts.tv_sec+(double)ts.tv_nsec/1e9;}

const char*htb_status_name(htb_status s){switch(s){case HTB_STATUS_READY:return"Ready";case HTB_STATUS_COMPUTING:return"Computing";case HTB_STATUS_COMPLETED:return"Completed";case HTB_STATUS_CANCELLED:return"Cancelled";case HTB_STATUS_UNRESOLVED:return"Unresolved crossing";case HTB_STATUS_VERTEX:return"Vertex collision";case HTB_STATUS_DEGENERATE:return"Degenerate geometry";case HTB_STATUS_RESOURCE_LIMIT:return"Resource limit";case HTB_STATUS_INVALID_INPUT:return"Invalid input";case HTB_STATUS_INTERNAL_ERROR:return"Internal error";}return"Internal error";}

static int scalar_norm(htb_scalar*out,const htb_vec2*v){htb_scalar a,b;htb_scalar_init(out->ctx,&a);htb_scalar_init(out->ctx,&b);int ok=htb_scalar_sqr(&a,&v->x)&&htb_scalar_sqr(&b,&v->y)&&htb_scalar_add(out,&a,&b)&&htb_scalar_sqrt(out,out);htb_scalar_clear(&a);htb_scalar_clear(&b);return ok;}

static htb_tiling_config effective_tiling_config(const htb_run_request*request){
    if(request->tiling.id[0])return request->tiling;htb_tiling_config config;memset(&config,0,sizeof(config));
    snprintf(config.id,sizeof(config.id),"elliptical-square");snprintf(config.version,sizeof(config.version),"1");config.parameter_count=2;
    snprintf(config.parameters[0].key,sizeof(config.parameters[0].key),"centerX");snprintf(config.parameters[0].value,sizeof(config.parameters[0].value),"%s",request->center_x[0]?request->center_x:"0");
    snprintf(config.parameters[1].key,sizeof(config.parameters[1].key),"centerY");snprintf(config.parameters[1].value,sizeof(config.parameters[1].value),"%s",request->center_y[0]?request->center_y:"0");return config;
}

static void event_init(htb_arith_ctx*ctx,htb_event*e){memset(e,0,sizeof(*e));htb_vec2_init(ctx,&e->point);htb_vec2_init(ctx,&e->reference_point);htb_vec2_init(ctx,&e->incoming);htb_vec2_init(ctx,&e->outgoing);htb_scalar_init(ctx,&e->time);htb_scalar_init(ctx,&e->disk_displacement);htb_scalar_init(ctx,&e->reference_displacement);htb_scalar_init(ctx,&e->path_length);htb_scalar_init(ctx,&e->disk_clearance);htb_scalar_init(ctx,&e->reference_clearance);}
static void event_clear(htb_event*e){htb_vec2_clear(&e->point);htb_vec2_clear(&e->reference_point);htb_vec2_clear(&e->incoming);htb_vec2_clear(&e->outgoing);htb_scalar_clear(&e->time);htb_scalar_clear(&e->disk_displacement);htb_scalar_clear(&e->reference_displacement);htb_scalar_clear(&e->path_length);htb_scalar_clear(&e->disk_clearance);htb_scalar_clear(&e->reference_clearance);}
static int allocate_events(htb_trajectory_result*r,htb_arith_ctx*ctx,int requested){r->event_capacity=(size_t)requested+1;r->events=calloc(r->event_capacity,sizeof(*r->events));if(!r->events)return 0;for(size_t i=0;i<r->event_capacity;i++)event_init(ctx,&r->events[i]);return 1;}

static htb_status find_next(const htb_tiling*tiling,htb_intersection_list*set,const htb_vec2*p,const htb_vec2*v,
                            const htb_tile_id*tile,const char*entry_boundary,int*best,int*other,char*error,size_t error_size){
    if(!tiling->definition->ops.intersections(tiling,p,v,tile,entry_boundary,set,error,error_size))return HTB_STATUS_INTERNAL_ERROR;
    int*active=calloc(set->count?set->count:1,sizeof(*active));if(!active)return HTB_STATUS_INTERNAL_ERROR;int count=0,ambiguous_a=-1,ambiguous_b=-1,winner=-1;*other=-1;
    for(size_t i=0;i<set->count;i++)if(set->items[i].state!=HTB_INTERSECTION_INVALID)active[count++]=(int)i;
    if(!count){free(active);return HTB_STATUS_DEGENERATE;}
    for(int a=0;a<count&&winner<0;a++){int i=active[a],minimum=set->items[i].has_time;
      for(int b=0;b<count&&minimum;b++)if(a!=b){int j=active[b];if(!set->items[j].has_time){minimum=0;if(ambiguous_a<0){ambiguous_a=i;ambiguous_b=j;}break;}htb_cmp order=htb_scalar_compare(&set->items[i].time,&set->items[j].time);
        if(order==HTB_CMP_GREATER){minimum=0;break;}if(order==HTB_CMP_UNRESOLVED||order==HTB_CMP_ERROR){minimum=0;if(ambiguous_a<0){ambiguous_a=i;ambiguous_b=j;}break;}}
      if(minimum)winner=i;}
    if(winner<0){*best=ambiguous_a>=0?ambiguous_a:active[0];*other=ambiguous_b;free(active);return HTB_STATUS_UNRESOLVED;}
    *best=winner;if(set->items[winner].state==HTB_INTERSECTION_UNRESOLVED){free(active);return HTB_STATUS_UNRESOLVED;}
    for(int a=0;a<count;a++){int j=active[a];if(j==winner||!set->items[j].has_time)continue;htb_cmp order=htb_scalar_compare(&set->items[winner].time,&set->items[j].time);if(order!=HTB_CMP_EQUAL)continue;*other=j;
      if(set->items[j].state==HTB_INTERSECTION_UNRESOLVED){free(active);return HTB_STATUS_UNRESOLVED;}
      if(strcmp(set->items[j].edge.boundary_key,set->items[winner].edge.boundary_key)!=0){free(active);return HTB_STATUS_VERTEX;}
      if(set->items[j].state==HTB_INTERSECTION_TANGENT){free(active);return HTB_STATUS_DEGENERATE;}}
    htb_status status=set->items[winner].state==HTB_INTERSECTION_TANGENT?HTB_STATUS_DEGENERATE:HTB_STATUS_COMPLETED;free(active);return status;
}

static const char*intersection_state_name(htb_intersection_state s){return s==HTB_INTERSECTION_VALID?"certified crossing":s==HTB_INTERSECTION_TANGENT?"certified tangency":s==HTB_INTERSECTION_UNRESOLVED?"unresolved candidate":"invalid candidate";}
static void add_competing(htb_trajectory_result*r,const htb_intersection*c){if(r->competing_count>=HTB_MAX_COMPETING_CANDIDATES)return;int n=r->competing_count++;snprintf(r->competing_edge_labels[n],sizeof(r->competing_edge_labels[n]),"%s",c->edge.label);snprintf(r->competing_states[n],sizeof(r->competing_states[n]),"%s",intersection_state_name(c->state));if(c->has_time)htb_scalar_get_enclosure(&c->time,30,r->competing_times[n],sizeof(r->competing_times[n]));else snprintf(r->competing_times[n],sizeof(r->competing_times[n]),"not bounded: candidate time unresolved");size_t used=strlen(r->competing_edges);snprintf(r->competing_edges+used,sizeof(r->competing_edges)-used,"%s%s",used?" / ":"",c->edge.label);}

static void set_uncertainty(htb_trajectory_result*r,int bounce,const htb_tile_id*tile,const htb_intersection_list*set,int best,int other,htb_status status,long precision,const char*reason){
    r->uncertainty_bounce=bounce;r->uncertainty_tile=*tile;r->maximum_precision=precision;r->competing_count=0;r->competing_edges[0]=0;
    if(best>=0&&(size_t)best<set->count)add_competing(r,&set->items[best]);if(status==HTB_STATUS_VERTEX&&best>=0&&(size_t)best<set->count&&set->items[best].has_time){for(size_t i=0;i<set->count;i++)if((int)i!=best&&set->items[i].state!=HTB_INTERSECTION_INVALID&&set->items[i].has_time&&htb_scalar_compare(&set->items[best].time,&set->items[i].time)==HTB_CMP_EQUAL)add_competing(r,&set->items[i]);}
    else if(other>=0&&(size_t)other<set->count)add_competing(r,&set->items[other]);snprintf(r->uncertainty_reason,sizeof(r->uncertainty_reason),"%s",reason);
    snprintf(r->status_detail,sizeof(r->status_detail),"Trajectory %s stopped before bounce %d in tile %s: %s (%s).",r->id,bounce,tile->label,reason,r->competing_edges);
}

static const char*unresolved_reason(const htb_intersection_list*set,int a,int b){if(a>=0&&b>=0&&(size_t)a<set->count&&(size_t)b<set->count&&set->items[a].state!=HTB_INTERSECTION_UNRESOLVED&&set->items[b].state!=HTB_INTERSECTION_UNRESOLVED)return"certified collision-time enclosures overlap, so their ordering is not proved; no vertex equality was proved";return"a candidate's forward-time or geometric-validity predicates remain unresolved; no vertex equality was proved";}

static int fill_diagnostics(const htb_tiling*tiling,htb_event*e,const htb_vec2*true_start,const htb_vec2*true_reference,int true_reference_available,const htb_event*previous){
    htb_arith_ctx*ctx=e->point.x.ctx;htb_scalar d1,d2,segment;htb_scalar_init(ctx,&d1);htb_scalar_init(ctx,&d2);htb_scalar_init(ctx,&segment);int ok=1;
    char ignored[160]={0};if(tiling->definition->ops.to_reference&&tiling->definition->ops.to_reference(tiling,&e->point,&e->reference_point,ignored,sizeof(ignored)))e->reference_available=1;
    if(previous)ok=htb_point_distance(&e->disk_displacement,&e->point,true_start);else ok=htb_scalar_set_si(&e->disk_displacement,0);
    if(ok&&e->reference_available&&true_reference_available){if(previous)ok=htb_point_distance(&e->reference_displacement,&e->reference_point,true_reference);else ok=htb_scalar_set_si(&e->reference_displacement,0);}else if(ok)ok=htb_scalar_set_si(&e->reference_displacement,0);
    htb_vec2 da,db,ra,rb;htb_vec2_init(ctx,&da);htb_vec2_init(ctx,&db);htb_vec2_init(ctx,&ra);htb_vec2_init(ctx,&rb);
    if(ok&&tiling->definition->ops.edge_vertices&&tiling->definition->ops.edge_vertices(tiling,&e->tile_before,&e->edge,&da,&db,&ra,&rb,ignored,sizeof(ignored))){
      ok=htb_point_distance(&d1,&e->point,&da)&&htb_point_distance(&d2,&e->point,&db);if(ok){htb_cmp c=htb_scalar_compare(&d1,&d2);ok=c==HTB_CMP_UNRESOLVED?htb_scalar_hull(&e->disk_clearance,&d1,&d2):htb_scalar_set(&e->disk_clearance,c==HTB_CMP_GREATER?&d2:&d1);}
      if(ok&&e->reference_available){ok=htb_point_distance(&d1,&e->reference_point,&ra)&&htb_point_distance(&d2,&e->reference_point,&rb);if(ok){htb_cmp c=htb_scalar_compare(&d1,&d2);ok=c==HTB_CMP_UNRESOLVED?htb_scalar_hull(&e->reference_clearance,&d1,&d2):htb_scalar_set(&e->reference_clearance,c==HTB_CMP_GREATER?&d2:&d1);}}else if(ok)ok=htb_scalar_set_si(&e->reference_clearance,0);if(ok)e->clearance_available=1;
    }else if(ok)ok=htb_scalar_set_si(&e->disk_clearance,0)&&htb_scalar_set_si(&e->reference_clearance,0);
    if(ok&&previous)ok=htb_point_distance(&segment,&e->point,&previous->point)&&htb_scalar_add(&e->path_length,&previous->path_length,&segment);else if(ok)ok=htb_scalar_set_si(&e->path_length,0);
    htb_vec2_clear(&da);htb_vec2_clear(&db);htb_vec2_clear(&ra);htb_vec2_clear(&rb);htb_scalar_clear(&d1);htb_scalar_clear(&d2);htb_scalar_clear(&segment);return ok;
}

static int record_event(htb_trajectory_result*r,const htb_tiling*tiling,int index,const htb_vec2*point,const htb_vec2*incoming,const htb_vec2*outgoing,const htb_scalar*time,
                        const htb_tile_id*before,const htb_tile_id*after,const htb_edge_ref*edge,const htb_vec2*true_start,const htb_vec2*true_reference,int true_reference_available,long precision){
    if(r->event_count>=r->event_capacity)return 0;htb_event*e=&r->events[r->event_count];e->index=index;e->tile_before=*before;e->tile_after=*after;e->edge=*edge;e->precision=precision;e->certified=1;
    int ok=htb_vec2_set(&e->point,point)&&htb_vec2_set(&e->incoming,incoming)&&htb_vec2_set(&e->outgoing,outgoing)&&htb_scalar_set(&e->time,time);
    if(ok)ok=fill_diagnostics(tiling,e,true_start,true_reference,true_reference_available,r->event_count?&r->events[r->event_count-1]:NULL);if(ok)htb_scalar_get_enclosure(&e->time,24,e->time_enclosure,sizeof(e->time_enclosure));if(ok)r->event_count++;return ok;
}

static int tile_seen(const htb_tile_id*tiles,int count,const htb_tile_id*tile){for(int i=0;i<count;i++)if(htb_tile_id_equal(&tiles[i],tile))return 1;return 0;}
static void count_tile(htb_trajectory_result*r,htb_tile_id*tiles,int*count,const htb_tile_id*tile){if(tile_seen(tiles,*count,tile))r->repeated_visits++;else{tiles[(*count)++]=*tile;r->unique_tiles=*count;}}

static void analyze_periodicity(htb_trajectory_result*r){snprintf(r->periodicity,sizeof(r->periodicity),"No periodic return observed");int undecidable=0;for(size_t j=1;j<r->event_count;j++)for(size_t i=0;i<j;i++){htb_event*a=&r->events[i],*b=&r->events[j];if(!htb_tile_id_equal(&a->tile_after,&b->tile_after)||strcmp(a->edge.boundary_key,b->edge.boundary_key)!=0)continue;htb_cmp c[4]={htb_scalar_compare(&a->point.x,&b->point.x),htb_scalar_compare(&a->point.y,&b->point.y),htb_scalar_compare(&a->outgoing.x,&b->outgoing.x),htb_scalar_compare(&a->outgoing.y,&b->outgoing.y)};int all=1;for(int k=0;k<4;k++){if(c[k]==HTB_CMP_UNRESOLVED)undecidable=1;if(c[k]!=HTB_CMP_EQUAL)all=0;}if(all){r->periodicity_start=(int)i;r->periodicity_period=(int)(j-i);snprintf(r->periodicity,sizeof(r->periodicity),"Exact periodicity verified");return;}if(r->arith->kind==HTB_BACKEND_ARB){double dx=htb_scalar_get_approx(&a->point.x)-htb_scalar_get_approx(&b->point.x),dy=htb_scalar_get_approx(&a->point.y)-htb_scalar_get_approx(&b->point.y);if(hypot(dx,dy)<1e-8)snprintf(r->periodicity,sizeof(r->periodicity),"Near return detected (not a proof)");}}if(undecidable&&r->arith->kind==HTB_BACKEND_CALCIUM)snprintf(r->periodicity,sizeof(r->periodicity),"Periodicity undecidable within current limits");}

static void emit_progress(htb_progress_fn fn,void*user,const char*type,const char*id,int bounce,long precision){if(!fn)return;json_t*o=json_object();json_object_set_new(o,"type",json_string(type));if(id)json_object_set_new(o,"trajectory",json_string(id));if(bounce>=0)json_object_set_new(o,"bounce",json_integer(bounce));if(precision>0)json_object_set_new(o,"precision",json_integer(precision));fn(o,user);json_decref(o);}

static htb_cmp directional_derivative(const htb_tiling*tiling,const htb_vec2*p,const htb_vec2*v,const htb_edge_ref*edge){htb_vec2 n;htb_vec2_init(p->x.ctx,&n);htb_scalar a,b,d;htb_scalar_init(p->x.ctx,&a);htb_scalar_init(p->x.ctx,&b);htb_scalar_init(p->x.ctx,&d);char error[80]={0};int ok=tiling->definition->ops.normal_at(tiling,edge,p,&n,error,sizeof(error))&&htb_scalar_mul(&a,&n.x,&v->x)&&htb_scalar_mul(&b,&n.y,&v->y)&&htb_scalar_add(&d,&a,&b);htb_cmp c=ok?htb_scalar_compare_si(&d,0):HTB_CMP_ERROR;htb_vec2_clear(&n);htb_scalar_clear(&a);htb_scalar_clear(&b);htb_scalar_clear(&d);return c;}
static void trajectory_values_init(htb_trajectory_result*r,htb_arith_ctx*ctx){htb_vec2_init(ctx,&r->launch);htb_vec2_init(ctx,&r->initial_direction);htb_vec2_init(ctx,&r->true_start);}

static htb_status simulate_once(const htb_run_request*request,const htb_trajectory_input*input,htb_trajectory_result*r,htb_arith_ctx*ctx,htb_progress_fn progress,void*progress_user){
    char error[256]={0};double started=now_seconds(),last_event_time=started;strncpy(r->id,input->id,sizeof(r->id)-1);r->requested_bounces=input->bounces;r->arith=ctx;r->maximum_precision=ctx->precision;trajectory_values_init(r,ctx);
    if(!allocate_events(r,ctx,input->bounces)){snprintf(r->status_detail,sizeof(r->status_detail),"event allocation failed");r->status=HTB_STATUS_INTERNAL_ERROR;return r->status;}
    htb_tiling_config config=effective_tiling_config(request);htb_tiling tiling;memset(&tiling,0,sizeof(tiling));htb_vec2 current,direction,true_reference;htb_vec2_init(ctx,&current);htb_vec2_init(ctx,&direction);htb_vec2_init(ctx,&true_reference);htb_scalar zero;htb_scalar_init(ctx,&zero);htb_scalar_set_si(&zero,0);htb_tile_id*visited=NULL;int visited_count=0,true_reference_available=0;htb_point_location location;htb_point_location_init(&location);
    int ok=htb_tiling_init(&tiling,ctx,&config,error,sizeof(error))&&htb_scalar_parse_rational(&r->launch.x,input->start_u,error,sizeof(error))&&htb_scalar_parse_rational(&r->launch.y,input->start_v,error,sizeof(error));
    if(ok&&input->uses_angle)ok=htb_scalar_set_sin_cos_degrees(&r->initial_direction.y,&r->initial_direction.x,input->angle_degrees,error,sizeof(error));else if(ok)ok=htb_scalar_parse_rational(&r->initial_direction.x,input->direction_u,error,sizeof(error))&&htb_scalar_parse_rational(&r->initial_direction.y,input->direction_v,error,sizeof(error));
    if(!ok){snprintf(r->status_detail,sizeof(r->status_detail),"%s",error);r->status=HTB_STATUS_INVALID_INPUT;goto finish;}
    htb_cmp inside;if(!htb_disk_contains(&r->launch,&inside)||inside!=HTB_CMP_LESS){snprintf(r->status_detail,sizeof(r->status_detail),inside==HTB_CMP_UNRESOLVED?"launch disk containment is unresolved":"launch must lie strictly inside the unit disk");r->status=inside==HTB_CMP_UNRESOLVED?HTB_STATUS_UNRESOLVED:HTB_STATUS_INVALID_INPUT;goto finish;}
    htb_scalar speed;htb_scalar_init(ctx,&speed);scalar_norm(&speed,&r->initial_direction);htb_cmp nonzero=htb_scalar_compare_si(&speed,0);htb_scalar_clear(&speed);if(nonzero!=HTB_CMP_GREATER){snprintf(r->status_detail,sizeof(r->status_detail),"initial direction must be certifiably nonzero");r->status=nonzero==HTB_CMP_UNRESOLVED?HTB_STATUS_UNRESOLVED:HTB_STATUS_INVALID_INPUT;goto finish;}
    if(!tiling.definition->ops.locate_point(&tiling,&r->launch,&location,error,sizeof(error))){snprintf(r->status_detail,sizeof(r->status_detail),"%s",error);r->status=HTB_STATUS_UNRESOLVED;goto finish;}
    if(location.incident_edges.count>1){snprintf(r->status_detail,sizeof(r->status_detail),"launch point is a tiling vertex; the initial tile is ambiguous");r->status=HTB_STATUS_INVALID_INPUT;goto finish;}
    visited=calloc((size_t)input->bounces+3,sizeof(*visited));if(!visited){r->status=HTB_STATUS_INTERNAL_ERROR;snprintf(r->status_detail,sizeof(r->status_detail),"visited-tile allocation failed");goto finish;}
    htb_vec2_set(&current,&r->launch);htb_vec2_set(&direction,&r->initial_direction);htb_tile_id tile=location.tile;char entry_boundary[HTB_TILING_KEY_MAX]={0};
    if(location.incident_edges.count==1){htb_edge_ref owner_edge=location.incident_edges.items[0];htb_cmp d=directional_derivative(&tiling,&current,&direction,&owner_edge);if(d!=HTB_CMP_LESS&&d!=HTB_CMP_GREATER){snprintf(r->status_detail,sizeof(r->status_detail),"launch direction is tangent to the starting edge or its side is unresolved");r->status=d==HTB_CMP_UNRESOLVED?HTB_STATUS_UNRESOLVED:HTB_STATUS_INVALID_INPUT;goto finish;}
      htb_adjacency a;if(!tiling.definition->ops.adjacent(&tiling,&tile,&owner_edge,&a,error,sizeof(error))){r->status=HTB_STATUS_INTERNAL_ERROR;snprintf(r->status_detail,sizeof(r->status_detail),"%s",error);goto finish;}int into_owner=(d==HTB_CMP_GREATER?1:-1)*owner_edge.owner_normal_sign>0;htb_tile_id before=into_owner?a.neighbor:tile,after=into_owner?tile:a.neighbor;htb_edge_ref crossed=into_owner?a.neighbor_edge:owner_edge;tile=after;r->initial_tile=after;htb_vec2_set(&r->true_start,&current);if(tiling.definition->ops.to_reference&&tiling.definition->ops.to_reference(&tiling,&r->true_start,&true_reference,error,sizeof(error)))true_reference_available=1;
      if(!record_event(r,&tiling,0,&current,&direction,&direction,&zero,&before,&after,&crossed,&r->true_start,&true_reference,true_reference_available,ctx->precision)){r->status=HTB_STATUS_INTERNAL_ERROR;snprintf(r->status_detail,sizeof(r->status_detail),"failed to record boundary launch");goto finish;}snprintf(entry_boundary,sizeof(entry_boundary),"%s",crossed.boundary_key);count_tile(r,visited,&visited_count,&tile);r->events[r->event_count-1].unique_tiles=r->unique_tiles;r->events[r->event_count-1].repeated_visits=r->repeated_visits;r->events[r->event_count-1].runtime_seconds=now_seconds()-last_event_time;last_event_time=now_seconds();emit_progress(progress,progress_user,"bounce",r->id,0,ctx->precision);
    }else{r->initial_tile=tile;count_tile(r,visited,&visited_count,&tile);htb_intersection_list set;htb_intersection_list_init(&set,ctx);int best=-1,other=-1;htb_status found=find_next(&tiling,&set,&current,&direction,&tile,NULL,&best,&other,error,sizeof(error));r->candidates_examined+=set.count;
      if(found!=HTB_STATUS_COMPLETED){r->status=found;const char*reason=found==HTB_STATUS_VERTEX?"the candidate collision times were proved equal on incident edges":found==HTB_STATUS_UNRESOLVED?unresolved_reason(&set,best,other):"the earliest event is tangent or boundary-coincident; no continuation was chosen";set_uncertainty(r,0,&tile,&set,best,other,found,ctx->precision,reason);htb_intersection_list_clear(&set);goto finish;}
      htb_intersection*c=&set.items[best];htb_vec2 normal,out;htb_vec2_init(ctx,&normal);htb_vec2_init(ctx,&out);htb_adjacency a;ok=tiling.definition->ops.normal_at(&tiling,&c->edge,&c->point,&normal,error,sizeof(error))&&htb_negative_refract(&out,&direction,&normal)&&tiling.definition->ops.adjacent(&tiling,&tile,&c->edge,&a,error,sizeof(error));
      if(ok){htb_vec2_set(&r->true_start,&c->point);if(tiling.definition->ops.to_reference&&tiling.definition->ops.to_reference(&tiling,&r->true_start,&true_reference,error,sizeof(error)))true_reference_available=1;ok=record_event(r,&tiling,0,&c->point,&direction,&out,&c->time,&tile,&a.neighbor,&c->edge,&r->true_start,&true_reference,true_reference_available,ctx->precision);}
      if(!ok){r->status=HTB_STATUS_INTERNAL_ERROR;snprintf(r->status_detail,sizeof(r->status_detail),"failed to record initialization crossing: %s",error);htb_vec2_clear(&normal);htb_vec2_clear(&out);htb_intersection_list_clear(&set);goto finish;}
      tile=a.neighbor;snprintf(entry_boundary,sizeof(entry_boundary),"%s",c->edge.boundary_key);htb_vec2_set(&current,&c->point);htb_vec2_set(&direction,&out);count_tile(r,visited,&visited_count,&tile);r->events[r->event_count-1].unique_tiles=r->unique_tiles;r->events[r->event_count-1].repeated_visits=r->repeated_visits;r->events[r->event_count-1].runtime_seconds=now_seconds()-last_event_time;last_event_time=now_seconds();r->total_tile_crossings=1;htb_vec2_clear(&normal);htb_vec2_clear(&out);htb_intersection_list_clear(&set);emit_progress(progress,progress_user,"bounce",r->id,0,ctx->precision);}
    for(int bounce=1;bounce<=input->bounces;bounce++){htb_intersection_list set;htb_intersection_list_init(&set,ctx);int best=-1,other=-1;htb_status found=find_next(&tiling,&set,&current,&direction,&tile,entry_boundary,&best,&other,error,sizeof(error));r->candidates_examined+=set.count;
      if(found!=HTB_STATUS_COMPLETED){r->status=found;const char*reason=found==HTB_STATUS_VERTEX?"the candidate collision times were proved equal on incident edges":found==HTB_STATUS_UNRESOLVED?unresolved_reason(&set,best,other):"the earliest event is tangent or boundary-coincident; no continuation was chosen";set_uncertainty(r,bounce,&tile,&set,best,other,found,ctx->precision,reason);htb_intersection_list_clear(&set);goto finish;}
      htb_intersection*c=&set.items[best];htb_vec2 normal,out;htb_vec2_init(ctx,&normal);htb_vec2_init(ctx,&out);htb_adjacency a;ok=tiling.definition->ops.normal_at(&tiling,&c->edge,&c->point,&normal,error,sizeof(error))&&htb_negative_refract(&out,&direction,&normal)&&tiling.definition->ops.adjacent(&tiling,&tile,&c->edge,&a,error,sizeof(error))&&record_event(r,&tiling,bounce,&c->point,&direction,&out,&c->time,&tile,&a.neighbor,&c->edge,&r->true_start,&true_reference,true_reference_available,ctx->precision);
      if(!ok){r->status=HTB_STATUS_INTERNAL_ERROR;snprintf(r->status_detail,sizeof(r->status_detail),"arithmetic failure while recording bounce %d: %s",bounce,error);htb_vec2_clear(&normal);htb_vec2_clear(&out);htb_intersection_list_clear(&set);goto finish;}
      tile=a.neighbor;snprintf(entry_boundary,sizeof(entry_boundary),"%s",c->edge.boundary_key);htb_vec2_set(&current,&c->point);htb_vec2_set(&direction,&out);count_tile(r,visited,&visited_count,&tile);r->events[r->event_count-1].unique_tiles=r->unique_tiles;r->events[r->event_count-1].repeated_visits=r->repeated_visits;r->events[r->event_count-1].runtime_seconds=now_seconds()-last_event_time;last_event_time=now_seconds();r->completed_bounces=bounce;r->total_tile_crossings=bounce+1;htb_vec2_clear(&normal);htb_vec2_clear(&out);htb_intersection_list_clear(&set);emit_progress(progress,progress_user,"bounce",r->id,bounce,ctx->precision);}
    r->status=HTB_STATUS_COMPLETED;snprintf(r->status_detail,sizeof(r->status_detail),"Completed %d post-initialization bounces.",input->bounces);
finish:r->runtime_seconds=now_seconds()-started;analyze_periodicity(r);free(visited);htb_point_location_clear(&location);htb_scalar_clear(&zero);htb_vec2_clear(&current);htb_vec2_clear(&direction);htb_vec2_clear(&true_reference);htb_tiling_clear(&tiling);return r->status;
}

static void trajectory_result_release(htb_trajectory_result*r,int free_context){if(r->events){for(size_t i=0;i<r->event_capacity;i++)event_clear(&r->events[i]);free(r->events);}if(r->arith){htb_vec2_clear(&r->launch);htb_vec2_clear(&r->initial_direction);htb_vec2_clear(&r->true_start);}htb_arith_ctx*ctx=r->arith;if(free_context&&ctx){htb_arith_ctx_clear(ctx);free(ctx);}memset(r,0,sizeof(*r));}

int htb_run(const htb_run_request*request,htb_run_result*result,htb_progress_fn progress,void*progress_user){memset(result,0,sizeof(*result));snprintf(result->run_id,sizeof(result->run_id),"%s",request->run_id);result->backend=request->backend;result->trajectory_count=request->trajectory_count;result->tiling=effective_tiling_config(request);result->status=HTB_STATUS_COMPUTING;double started=now_seconds();emit_progress(progress,progress_user,"run_started",NULL,-1,request->initial_precision);int all_completed=1;
    for(int n=0;n<request->trajectory_count;n++){emit_progress(progress,progress_user,"trajectory_started",request->trajectories[n].id,-1,request->initial_precision);long precision=request->backend==HTB_BACKEND_ARB?request->initial_precision:request->max_precision;uint64_t refinements=0;for(;;){htb_arith_ctx*ctx=calloc(1,sizeof(*ctx));char error[256]={0};if(!ctx||!htb_arith_ctx_init(ctx,request->backend,precision,request->max_precision,error,sizeof(error))){if(ctx)free(ctx);result->trajectories[n].status=HTB_STATUS_INTERNAL_ERROR;snprintf(result->trajectories[n].status_detail,sizeof(result->trajectories[n].status_detail),"arithmetic context failed: %s",error);all_completed=0;break;}htb_trajectory_result attempt;memset(&attempt,0,sizeof(attempt));simulate_once(request,&request->trajectories[n],&attempt,ctx,progress,progress_user);attempt.precision_refinements=refinements;attempt.comparison_retries=refinements;attempt.maximum_precision=precision;if(request->backend==HTB_BACKEND_ARB&&attempt.status==HTB_STATUS_UNRESOLVED&&precision<request->max_precision){long next=precision>request->max_precision/2?request->max_precision:precision*2;trajectory_result_release(&attempt,1);precision=next;refinements++;emit_progress(progress,progress_user,"precision_increased",request->trajectories[n].id,-1,precision);continue;}result->trajectories[n]=attempt;if(attempt.status!=HTB_STATUS_COMPLETED)all_completed=0;emit_progress(progress,progress_user,"trajectory_finished",attempt.id,attempt.completed_bounces,precision);break;}}
    result->runtime_seconds=now_seconds()-started;result->status=HTB_STATUS_COMPLETED;if(!all_completed)for(int n=0;n<result->trajectory_count;n++)if(result->trajectories[n].status!=HTB_STATUS_COMPLETED){result->status=result->trajectories[n].status;break;}snprintf(result->status_detail,sizeof(result->status_detail),"%s",all_completed?"All enabled trajectories completed.":"One or more trajectories returned a certified partial result; see per-trajectory status.");struct rusage usage;if(getrusage(RUSAGE_SELF,&usage)==0){
#ifdef __APPLE__
      result->peak_memory_kb=(long)(usage.ru_maxrss/1024);
#else
      result->peak_memory_kb=(long)usage.ru_maxrss;
#endif
    }for(int n=0;n<result->trajectory_count;n++)if(result->trajectories[n].arith){htb_arith_ctx*c=result->trajectories[n].arith;result->comparisons+=c->comparisons;result->unresolved_comparisons+=c->unresolved_comparisons;result->candidates_examined+=result->trajectories[n].candidates_examined;if(result->trajectories[n].maximum_precision>result->maximum_precision)result->maximum_precision=result->trajectories[n].maximum_precision;}if(request->memory_limit_mb>0&&result->peak_memory_kb>(long)(request->memory_limit_mb*1024)){result->status=HTB_STATUS_RESOURCE_LIMIT;snprintf(result->status_detail,sizeof(result->status_detail),"Memory budget exceeded; partial results are preserved.");}emit_progress(progress,progress_user,"run_finished",NULL,-1,result->maximum_precision);return 1;}

void htb_run_result_clear(htb_run_result*result){for(int i=0;i<result->trajectory_count;i++)trajectory_result_release(&result->trajectories[i],1);memset(result,0,sizeof(*result));}
